  str_quest_base_dayli_tips_awards_got = "報酬は受け取り済みです",
  str_quest_base_story_new_chapter_open = "新章任務解放",
  str_quest_base_daily_reset_tips = "デイリー任務はリセット済です",
  str_quest_base_awards_info_look = "報酬プレビュー",
  str_quest_base_story_chapter_index = "第%s章",
  str_quest_base_story_all_chapter_clean = "全章の任務をクリア！",
  str_quest_base_story_current_chapter_clean = "この章の任務は全てクリア済です",
  str_quest_base_story_click_lock_chapter = "前章のストーリー任務をクリア後に解放",
  str_quest_base_desc_101 = "ソラヴァンの主よ、ここが旅の始まりだ。予期せぬ収穫、突然襲い来る災難、苦境の中に見える希望、そして強いられる成長…成長には常に激しい痛みが伴う。それが避けられないものならば、快楽として味わうのだ。すべての苦しみは、将来価値あるものになるだろう。\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_102 = "初めての世界での体験、さぞ戸惑っているのではないか？だが、危機には冷静に対処し、絆を大切にしてほしい。そなたが出会うすべての人と物事はアストラの一部であり、最後には極光の一部となる。そなた自身でさえも…受け入れ、理解し、行動を振り返り、成長し続けるのだ。\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_103 = "過去からの反響が再び波紋を広げ、同胞、敵、戦友が次々と現れる。希望につながる転機や手痛い挫折にどう対処するか、個人的な憎しみと新たな仲間たちとの「使命」にどう折り合いをつけるかは、そなたが血と涙を流して学ばなければならない課題であろう。\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_104 = "そなたはもう己の目標を理解したであろう？そして同族以外の者からも認められたのではないか？ この先には光霊の最後の都、天空に浮かぶ島がある。そなたはそこで新たな絆を見つけ、闇を切り開く旅に向けて、着実な一歩を踏み出すであろう。\n  ――ベツレヘム",
  str_quest_base_desc_105 = "生まれつき退却を知らぬ猛獣のように、前途なき地で剣を振るい死に行く勇者のように、挫折と戦いを繰り返す。過去は繰り返しそなたを襲い、そして最大の恐怖に導くだろう。彼女の顔を見たら教えてほしい。それは誰であったのか…\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_106 = "歯がゆいのか？極光が示すように、そなたは間もなく谷底に至る。そこは怒りと恨みに満ちた泥沼、失敗と屈辱で築かれた牢獄だ。しかし、そこでこそ真の力――頑健な肉体ではなく未来を切り開く目と心――を得ることができるのだ。\n  ――ベツレヘム",
  str_quest_base_desc_107 = "空の末裔よ、私たちの対話は新たな段階へと入った。そなたが私の役割を理解できないように、私も理解する手段を持たない。それは不明瞭な予兆が書かれたわずかな言葉であるからだ。極光がかげり、白夜城の上空には翼を広げ、絶望した者がいる――彼女を凌駕するか、ここで終わるか…\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_108 = "最も暗い深淵の中であろうと、そなたは「予言」の日まで生き延びられた。私は、 心の中の言い表しがたい直感に従うべきだと信じている。 空の末裔よ、チャンスをつかめ。あの黒き要塞を、本来あるべき場所に戻すのだ！\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_109 = "私たちには2つの故郷がある。1つは足下に、1つは心の中に。幸運な者は両者に違いがないことに気付くであろう。しかし、大多数の苦悩する魂は両者の狭間でもがき続け、中には記憶の奥深くにある土地にもう二度と触れられない者すらいる。たとえ納得できなくても、どうしようもないのだ。\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_110 = "あの土地がそなたを成長させ、様々なことを思い出させる。それと同時に、安心して手放すことができるだろう。旅の終わりが待っている。自分の怒りや憎しみを存分に解き放ち、雲散霧消させるのだ。今度会う時には、新しい自分になっていてもらいたい。\n                                                                                                                       ――ベツレヘム",
  str_quest_base_desc_111 = "永久極夜。どの光霊も近づきたがらない領域、暗黒に呑み込まれた深淵だ。昼と夜の幕間に、一瞬の機会をつかめ。巨像の主よ、そなたが暗黒を切り裂き、宿願を果たすことを祈っている。\n\n――ベツレヘム",
  str_quest_base_desc_112 = "美しい花が鋭い棘に覆われているように、希望と試練は得てして表裏一体だ。満身の傷を負う覚悟が出来たのならば、始まりの地へと立ち戻るがいい。探し、失い、絶望にうなだれ…そして再び、その面を高く上げてみせるのだ。\n\n――ベツレヘム",
  str_quest_base_desc_113 = "真相の鋭い刃が胸を貫き、脆く弱った心臓を引き裂く。「なぜこうなる？」「そんなはずはない！」驚き、疑い、憤り。進むべき道を見失い、深淵の縁で虚しく空を見上げる。空の末裔よ、そなたの選ぶ未来は私にも見えない。私には、何も…\n\n――ベツレヘム",
  str_quest_base_desc_114 = "誰もが生涯、知を求め続ける。そなたは幸運だ。だが、悲しくもある。運命が授けた果てしなく広い世界を誰よりも遠くまで歩いて行ける力に恵まれながら、その道のりは孤独だった。そなたがどこを目指しているのか、私には分からない。そこが私の目の及ばない場所だと定められているからだ。\n――ベツレヘム",
  str_quest_base_desc_115 = "気付いたか？多くの出会いが訪れている。彼らはそれぞれ異なる場所から来たり、異なる場所へと向かい、その途上で、そなたの進む道と交わったにすぎない。大空の下には多くの人々が暮らし、太陽をいただく幸運の持ち主は最も豊かな日差しを浴びている。だが、夕陽の傍らにたたずむ子どもたちもまた、太陽にもっとも近い場所にいるのだ。\n――ベツレヘム",
  str_quest_base_desc_116 = "宿敵と行動を共にせねばならぬとは、何と皮肉な運命だろう。その先に待っているのが火の海であろうと、底なし沼であろうと、そなたには仲間たちと共に立ち向かうほか、選択肢は残されていないようだ。\n――ベツレヘム",
  str_quest_base_desc_117 = "戦場は陰謀をもくろむ者たちの舞台だ。何も知らない観客たちはあちこちから集まってくる。果てなき闇夜が目の前に迫っていながら、光霊たちはまだそれぞれの美しい夢から目を覚まさずにいるのだ。\n――ベツレヘム",
  str_quest_base_desc_118 = "権力が交代する時、かつて運命に恵まれなかった者が多くの人々が注目する中、この世界の表舞台に登場する。しかし、野心は戦場で最も無意味な武器だ。過去の自分を葬ってこそ、政治の闇が渦巻く中から抜け出し、再び生を得ることができるのだ。\n――ベツレヘム",
  str_quest_base_desc_119 = "力とは己が動かすことによって湧いてくるのか、それとも他者が授けてくれたものなのか？強靭な肉体が泥沼の中に埋もれていくのを目にした時、人はようやく悟る。脆さこそ命の本質なのだと。\n――ベツレヘム",
  str_quest_base_desc_120 = "見知らぬ存在が600年あまりの時を経て、ついに啓光と手を結んだ。歴史のページをめくって可能性を探るべきか、それとも過去を捨てて新しい道を切り開くべきか？これは現在の疑問であり、何代にもわたって光霊を悩ませ続けてきた謎でもある。\n――ベツレヘム",
  str_quest_base_desc_121 = "仲間たちと数え切れないほどの楽しい時間を過ごしたそなたは、別れの時が突然やって来るとは思いもしなかったであろう。「過去からの信号」が再び点灯する。今回はそなたが成長し、未知なる遺跡を探索して自分の過去を探らなければならない。\n――ベツレヘム",
  str_quest_base_desc_122 = "この先の道に灯台を建てながら進め。北境の女王である私の言葉だ。\n——ベツレヘム",
  str_quest_base_type_stroy_with_space = "ストーリー",
  str_quest_base_type_daily_with_space = "デイリー",
