  str_quest_base_achieve_type_407_space = "巨像",
  str_quest_base_achieve_finish_list_title = "以下の任務を完了しました",
  str_quest_base_desc_123 = "そなたはすでに極夜を目にしたが、心の中の信念ははっきりとしたか？この世では、あまりにも多くの人々が暗闇の行き詰まりに囚われ、かすかな希望を追い求めている。しかし、そなたにとって、それは幻ではない。\nそなたはその希望を常につかんではなさないだろう。なぜなら、この物語はそなたが英勇の道を歩み始めたときより始まっているからだ。そなたはその光の点を守り、希望もそなたのために続いていく。そのことを信じ、揺るぐことなく歩み続けるのだ。\n――ベツレヘム",
